Here is the commit message:
rxrpc: Fix buffer overread in rxgk_do_verify_authenticator()

Fix rxgk_do_verify_authenticator() to check the buffer size before checking
the nonce.

Fixes: 9d1d2b59341f ("rxrpc: rxgk: Implement the yfs-rxgk security class (GSSAPI)")
Closes: https://sashiko.dev/#/patchset/20260401105614.1696001-10-dhowells@redhat.com
Signed-off-by: David Howells <dhowells@redhat.com>
cc: Marc Dionne <marc.dionne@auristor.com>
cc: Jeffrey Altman <jaltman@auristor.com>
cc: Simon Horman <horms@kernel.org>
cc: linux-afs@lists.infradead.org
cc: stable@kernel.org
Link: https://patch.msgid.link/20260408121252.2249051-20-dhowells@redhat.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The function rxgk_do_verify_authenticator() did not check that the remaining buffer size is sufficient to contain the nonce (20 bytes) before performing a memcmp operation, leading to a potential buffer overread when processing a malformed packet.

Here is the patch:
  */
 static int rxgk_do_verify_authenticator(struct rxrpc_connection *conn,
 					const struct krb5_enctype *krb5,
 					struct sk_buff *skb,
 					__be32 *p, __be32 *end)
 {
 	u32 app_len, call_count, level, epoch, cid, i;

 	_enter("");

+	if ((end - p) * sizeof(__be32) < 24)
+		return rxrpc_abort_conn(conn, skb, RXGK_NOTAUTH, -EPROTO,
+					rxgk_abort_resp_short_auth);
 	if (memcmp(p, conn->rxgk.nonce, 20) != 0)
 		return rxrpc_abort_conn(conn, skb, RXGK_NOTAUTH, -EPROTO,
 					rxgk_abort_resp_bad_nonce);
 	p += 20 / sizeof(__be32);

 	app_len	= ntohl(*p++);
 	if (app_len > (end - p) * sizeof(__be32))
 		return rxrpc_abort_conn(conn, skb, RXGK_NOTAUTH, -EPROTO,
 					rxgk_abort_resp_short_applen);

 	p += xdr_round_up(app_len) / sizeof(__be32);
 	if (end - p < 4)
 		return rxrpc_abort_conn(conn, skb, RXGK_NOTAUTH, -EPROTO,
-					rxgk_abort_resp_short_applen);
+					rxgk_abort_resp_short_auth);

 	level	= ntohl(*p++);
 	epoch	= ntohl(*p++);
 	cid	= ntohl(*p++);
 	call_count = ntohl(*p++);

 	if (level	!= conn->security_level ||
 	    epoch	!= conn->proto.epoch ||
 	    cid		!= conn->proto.cid ||
 	    call_count	> 4)
 		return rxrpc_abort_conn(conn, skb, RXGK_NOTAUTH, -EPROTO,
 					rxgk_abort_resp_bad_param);

 	if (end - p < call_count)
 		return rxrpc_abort_conn(conn, skb, RXGK_NOTAUTH, -EPROTO,
 					rxgk_abort_resp_short_call_list);

 	for (i = 0; i < call_count; i++) {
 		u32 call_id = ntohl(*p++);

 		if (call_id > INT_MAX)
 			return rxrpc_abort_conn(conn, skb, RXGK_NOTAUTH, -EPROTO,
 						rxgk_abort_resp_bad_callid);

 		if (call_id < conn->channels[i].call_counter)
 			return rxrpc_abort_conn(conn, skb, RXGK_NOTAUTH, -EPROTO,
 						rxgk_abort_resp_call_ctr);

 		if (call_id > conn->channels[i].call_counter) {
 			if (conn->channels[i].call)
 				return rxrpc_abort_conn(conn, skb, RXGK_NOTAUTH, -EPROTO,
 							rxgk_abort_resp_call_state);

 			conn->channels[i].call_counter = call_id;
 		}
 	}

 	_leave(" = 0");
 	return 0;
 }



